// Optional styling metadata on the existing editable shape geometry.
export const TERRAIN_TYPES={'tree':['ellipse'],'rock':['room'],'water':['room'],'bridge':['rect'],'ford':['rect'],'clearing':['ellipse'],'trail':['room'],'rubble':['ellipse'],'ruin-floor':['rect'],'ruin-wall':['wall','path'],'cave-floor':['room'],'cave-wall':['room','path']};
export const terrainNames={'tree':'Baum','rock':'Fels','water':'Fluss','bridge':'Brücke','ford':'Furt','clearing':'Lichtung','trail':'Weg','rubble':'Trümmer','ruin-floor':'Ruinenboden','ruin-wall':'Ruinenwand','cave-floor':'Höhlenboden','cave-wall':'Höhlenwand'};
export const shapeLayer=s=>s.type==='door'?5:['cave-floor','ruin-floor','clearing'].includes(s.terrain)?-3:['water','trail'].includes(s.terrain)?-2:['tree','rock','rubble'].includes(s.terrain)?2:['bridge','ford'].includes(s.terrain)?3:Number(!!s.interior);
